    if (new_prop != NULL) {
        /* set placeholder until caller sets it to a real type */
        new_prop->type = MQTT_PROP_TYPE_MAX;
        if (prev == NULL) {
            /* Start a new list */
            *head = new_prop;
        }
        else {
            /* Add to the existing list */
            prev->next = new_prop;
        }
    }
    else {
        /* Could not allocate property */
        (void)MQTT_TRACE_ERROR(MQTT_CODE_ERROR_PROPERTY);
    }

